(* [comment removed for export] *)
Local Ltac fin_entry MS KS KSL MG FRZ X1 X2 RA :=
  split; [eapply msteps_trans; [exact MS| apply ret_div; [rewrite (KS 1%nat) by PMK.inl; exact X1| exact RA]]|];
  split; [exact MG|];
  split; [intros a Ha N1 N2; apply FRZ; [exact Ha| clear - N1; lia| clear - N2; lia]|];
  split; [intros i Hi; apply KS; revert Hi; apply (PMPK.sub_in KSL L5K.CS); vm_compute; reflexivity|];
  split; [rewrite (KS 2%nat) by PMK.inl; exact X2|].

