(* [comment removed for export] *)
Section Call.
Variables (fx0 : FPState) (R0 : bvmap 5 word) (M0 : word -> option byte) (model0 : Model) (K : TSet) (LB : list (Z * Z)) (cr0 : credit).
Variables (v a sp r g : Z) (x : PQV8.v8).
Hypothesis HH0 : hi_heap HI (PQV8.v8_own x ++ LB) cr0 M0 (m_vmmaps model0).
Hypothesis MOK : PMSP.model_ok model0.
Hypothesis K0 : K [].
Hypothesis Rra : getr R0 (PMK.reg 1) = Z_to_bv 64 r.
Hypothesis RAok : L5.ra_ok r.
Hypothesis Rsp : getr R0 (PMK.reg 2) = Z_to_bv 64 sp.
Hypothesis Rtp : getr R0 (PMK.reg 4) = Z_to_bv 64 0xd8850.
Hypothesis STK0 : L5C.stk (hl_sptop L) M0 sp (PMSP.pm_scr 1).
Hypothesis A10 : getr R0 (PMK.reg 10) = Z_to_bv 64 v.
Hypothesis A11 : getr R0 (PMK.reg 11) = Z_to_bv 64 a.
Hypothesis Hspv : sp <= v.
Hypothesis Hvtop : v + 24 <= hl_sptop L.
Hypothesis Hv8 : v mod 8 = 0.
Hypothesis VAT : PQV8.v8_at RSEGS PMSP.T3 PMSP.T4 M0 v x.
Hypothesis VOK : PQV8.v8_ok x g.
Hypothesis HA : 1 <= a /\ PQV8.v8_size x + a < 2 ^ 64.
Hypothesis GROW : PQV8.v8_grow_ok x (PQV8.v8_size x + a).
Hypothesis CRED : PMSP.credit_le (PQV8.pot_v8 L x g) cr0.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : PQV8.v8) (g' : Z) (cr' : credit),
        regs_preserved R0 R' -> PQV8.v8_at RSEGS PMSP.T3 PMSP.T4 M' v x' -> PQV8.v8_size x' = PQV8.v8_size x + a -> PQV8.v8_ok x' g' ->
        PQV8.v8_cap x <= PQV8.v8_cap x' ->
        (PQV8.v8_size x' <= PQV8.v8_cap x -> PQV8.v8_own x' = PQV8.v8_own x /\ PQV8.v8_cap x' = PQV8.v8_cap x /\ g' = g) ->
        L5C.hpres L LB sp (PMSP.pm_scr 1) [(v, 24)] M0 M' ->
        PMSP.credit_keep cr0 cr' (PQV8.pot_v8 L x g) (PQV8.pot_v8 L x' g') ->
        model_but_vm model0 model' -> hi_heap HI (PQV8.v8_own x' ++ LB) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

Let LBh : forall b, In b LB -> fst b + snd b <= hl_ceil L.
Proof. intros b Hb. exact (PMCK.lb_hi L HI HIok _ cr0 M0 _ HH0 b (in_or_app _ _ _ (or_intror Hb))). Qed.

(* [comment removed for export] *)
Let base_facts : 0 <= sp < 2 ^ 64 /\ 140735332483152 <= sp <= 140737488355328 /\ sp mod 16 = 0 /\ 0 <= v /\ v + 24 <= 2 ^ 47
  /\ 0 <= hl_k_per_malloc L /\ 0 <= hl_b_overhead L.
Proof.
  pose proof STK0 as (A16 & SLO & SHI & STOP & _). unfold PMSP.pm_scr in SLO. pose proof (ly_kpm L LY). pose proof (ly_bov L LY). repeat split; lia.
Qed.

(* [comment removed for export] *)
Lemma FITS b n c : x = PQV8.V8Blk b n c -> n + a <= c -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx0 R0 0x47360 M0 model0) K.
Proof.
