(* [comment removed for export] *)
Lemma GROW_TAIL (fx2 : FPState) R2 M2 model2 (NB newcap : Z) :
  let n := PQV8.v8_size x in let b := PQV8.v8_data x in let c := PQV8.v8_cap x in
  getr R2 (PMK.reg 2) = Z_to_bv 64 (sp - 80) -> getr R2 (PMK.reg 8) = Z_to_bv 64 v -> getr R2 (PMK.reg 9) = Z_to_bv 64 b ->
  getr R2 (PMK.reg 18) = Z_to_bv 64 a -> getr R2 (PMK.reg 19) = Z_to_bv 64 c -> getr R2 (PMK.reg 20) = Z_to_bv 64 n ->
  getr R2 (PMK.reg 21) = Z_to_bv 64 newcap -> getr R2 (PMK.reg 10) = Z_to_bv 64 NB ->
  (forall k, In k CSA -> getr R2 (PMK.reg k) = getr R0 (PMK.reg k)) ->
  (forall i, (i < 9)%nat -> L5.u64_at RSEGS M2 (sp - 8 * (Z.of_nat i + 1)) (bv_unsigned (getr R0 (PMK.reg (nth i [1; 8; 9; 18; 19; 20; 21; 22; 23]%nat 0%nat))))) ->
  L5C.stk (hl_sptop L) M2 sp (PMSP.pm_scr 1) ->
  PQV8.v8_at RSEGS PMSP.T3 PMSP.T4 M2 v x ->
  L5C.fresh_block L (PQV8.v8_own x ++ LB) M2 NB newcap ->
  n + a <= newcap -> 2 * c <= newcap -> newcap <= 2 ^ 27 + 2 ^ 15 -> c < n + a ->
  PMK.ek L LB sp (PMSP.pm_scr 1) [(v, 24)] M0 M2 -> PMK.dk L LB sp (PMSP.pm_scr 1) M0 M2 ->
  PMSP.model_ok model2 -> model_but_vm model0 model2 ->
  hi_heap HI ((NB, newcap) :: PQV8.v8_own x ++ LB) (debit L cr0 newcap) M2 (m_vmmaps model2) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 0x473dc M2 model2) K.
Proof.
