Lemma AT_OPNEW (fx1 : FPState) R1 M1 (newcap : Z) :
  let n := PQV8.v8_size x in let b := PQV8.v8_data x in let c := PQV8.v8_cap x in
  msteps RSEGS (@mkst fx0 R0 (Z_to_bv 64 0x47360) M0 (seg_rom RSEGS)) (@mkst fx1 R1 (Z_to_bv 64 0xbe8b0) M1 (seg_rom RSEGS)) ->
  mem_grows M0 M1 -> (forall q, 0 <= q < 2 ^ 64 -> ~ (sp - 80 <= q < sp) -> M1 (Z_to_bv 64 q) = M0 (Z_to_bv 64 q)) ->
  getr R1 (PMK.reg 1) = Z_to_bv 64 0x473dc -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 80) -> getr R1 (PMK.reg 8) = Z_to_bv 64 v ->
  getr R1 (PMK.reg 9) = Z_to_bv 64 b -> getr R1 (PMK.reg 10) = Z_to_bv 64 newcap -> getr R1 (PMK.reg 18) = Z_to_bv 64 a ->
  getr R1 (PMK.reg 19) = Z_to_bv 64 c -> getr R1 (PMK.reg 20) = Z_to_bv 64 n -> getr R1 (PMK.reg 21) = Z_to_bv 64 newcap ->
  (forall k, In k CSA -> getr R1 (PMK.reg k) = getr R0 (PMK.reg k)) ->
  (forall i, (i < 9)%nat -> L5.u64_at RSEGS M1 (sp - 8 * (Z.of_nat i + 1)) (bv_unsigned (getr R0 (PMK.reg (nth i [1; 8; 9; 18; 19; 20; 21; 22; 23]%nat 0%nat))))) ->
  n + a <= newcap -> 2 * c <= newcap -> newcap <= 2 ^ 27 + 2 ^ 15 -> c < n + a ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx0 R0 0x47360 M0 model0) K.
Proof.
